  function itemField(content,label){
    const hits=Array.from(content.querySelectorAll?.('strong,b')||[]).filter(el=>String(el.textContent||'').trim().replace(/:\s*$/,'').toLowerCase()===label.toLowerCase());
    const values=[];
    for(const marker of hits){let value='',n=marker.nextSibling;for(let i=0;n&&i<12;i++,n=n.nextSibling){if(['BR','STRONG','B','P','DIV','UL','OL'].includes(n.nodeName))break;value+=String(n.textContent||'')}value=value.trim().replace(/^:\s*/,'').replace(/\s+/g,' ');if(value&&value.length<=160)values.push(value)}
    const unique=[...new Set(values)];return unique.length===1?unique[0]:null;
  }
  function compactItemInformation(info,details,summary){
    if(!info||!details||!summary)return false;
    const doc=info.ownerDocument,heading=info.querySelector('.aqwc-item-section-label');
    const originals=[...info.childNodes].filter(n=>n!==heading);
    const detailHead=details.querySelector('.aqwc-item-section-label');
    const fragment=doc.createDocumentFragment();for(const n of originals)fragment.append(n);
    if(detailHead)detailHead.after(fragment);else details.prepend(fragment);
    function link(x){const a=doc.createElement('a');a.href=location.origin+'/'+x.slug+(x.hash||'');a.textContent=x.name;return a}
    function row(label){const n=doc.createElement('div');n.className='aqwc-info-line';const k=doc.createElement('strong');k.textContent=label+': ';n.append(k);info.append(n);return n}
    function linkedText(n,value,links){
      // Preserve the original shop/location pairing and punctuation, without cloning arbitrary HTML.
      let rest=value;
      for(const x of links){const i=rest.indexOf(x.name);if(i<0)continue;n.append(doc.createTextNode(rest.slice(0,i)),link(x));rest=rest.slice(i+x.name.length)}
      if(rest)n.append(doc.createTextNode(rest));
    }
    if(summary.description){const d=doc.createElement('p');d.className='aqwc-item-description';d.textContent=summary.description;d.title=summary.description;info.append(d)}
    if(summary.locations.length){const n=row(summary.locations.length>1?'Locations':'Location');summary.locations.forEach((l,i)=>{if(i)n.append(doc.createTextNode(' · '));linkedText(n,l.text,l.links)})}
    if(summary.prices.length){const n=row('Price');n.append(doc.createTextNode(summary.prices.join(' / ')))}
    for(const method of summary.methods){const n=row(method.label);if(method.links.length)method.links.forEach((x,i)=>{if(i)n.append(doc.createTextNode(' · '));n.append(link(x))});else n.append(doc.createTextNode('See Farming Progress or Wiki details'))}
    return true;
  }
